    async def create_export_job(
        self,
        *,
        region: str | None = None,
        organization_id: str | None = None,
        name: str | None = None,
        s3: ExportJobS3 | None = None,
        tags: list[str] | None = None,
    ) -> ExportJob:
        """
        Create an export job

        Create an export job for a specified organization. This allows you to export
        audit trail events to a destination, such as an S3 bucket. The request requires
        the organization ID, a name for the export, and a destination configuration.

        Args:
            region: The region you want to target
            organization_id: ID of the Organization to target.
            name: Name of the export.
            s3: The configuration specifying the bucket where the audit trail events
                will be exported. Precisely one of s3 can be set.
            tags: Tags of the export.
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/audit-trail/v1alpha1/regions/{region}/export-jobs",
                region=self._client.region(region),
            ),
            body={
                "organization_id": self._client.organization_id(organization_id),
                "name": name,
                "s3": s3,
                "tags": tags,
            },
        )
        return ExportJob.model_validate(data)

